const countItemsSQL = `SELECT COUNT(*) FROM sample_items WHERE sample_id = $1`
const listItemsSQL = `
SELECT id, name, status, created_at
FROM sample_items
WHERE sample_id = $1
ORDER BY id
LIMIT $2 OFFSET $3`

func parsePage(raw string) (int, error) {
    if raw == "" {
        return 1, nil
    }
    page, err := strconv.Atoi(raw)
    if err != nil || page < 1 || page > 10_000 {
        return 0, errors.New("page must be an integer between 1 and 10000")
    }
    return page, nil
}

func writeJSON(w http.ResponseWriter, status int, payload any) error {
    w.Header().Set("Content-Type", "application/json")
    w.WriteHeader(status)
    return json.NewEncoder(w).Encode(payload)
}

func writeError(w http.ResponseWriter, status int, message string) {
    _ = writeJSON(w, status, map[string]string{"error": message})
}

func (h *Handler) ListItems(w http.ResponseWriter, r *http.Request) {
    page, err := parsePage(r.URL.Query().Get("page"))
    if err != nil {
        writeError(w, http.StatusBadRequest, err.Error())
        return
    }
    sampleID, ok := auth.SampleID(r.Context())
    if !ok {
        writeError(w, http.StatusUnauthorized, "authentication required")
        return
    }

    const perPage = 20
    ctx, cancel := context.WithTimeout(r.Context(), 5*time.Second)
    defer cancel()

    var total int
    if err := h.db.QueryRowContext(ctx, countItemsSQL, sampleID).Scan(&total); err != nil {
        h.handleDatabaseError(ctx, w, err)
        return
    }
    rows, err := h.db.QueryContext(
        ctx, listItemsSQL, sampleID, perPage, (page-1)*perPage,
    )
    if err != nil {
        h.handleDatabaseError(ctx, w, err)
        return
    }
    defer rows.Close()

    items := make([]Item, 0, perPage)
    for rows.Next() {
        var item Item
        if err := rows.Scan(&item.ID, &item.Name, &item.Status, &item.CreatedAt); err != nil {
            h.log.ErrorContext(ctx, "list items row scan failed", "error", err)
            writeError(w, http.StatusInternalServerError, "internal server error")
            return
        }
        items = append(items, item)
    }
    if err := rows.Err(); err != nil {
        h.handleDatabaseError(ctx, w, err)
        return
    }
    payload := listResponse{Items: items, Page: page, PerPage: perPage, Total: total}
    if err := writeJSON(w, http.StatusOK, payload); err != nil {
        h.log.ErrorContext(ctx, "list items response encoding failed", "error", err)
    }
}

func (h *Handler) handleDatabaseError(ctx context.Context, w http.ResponseWriter, err error) {
    if errors.Is(ctx.Err(), context.DeadlineExceeded) {
        writeError(w, http.StatusGatewayTimeout, "request timed out")
        return
    }
    h.log.ErrorContext(ctx, "list items database operation failed", "error", err)
    writeError(w, http.StatusInternalServerError, "internal server error")
}

